node --env-file=.env -e "
const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);

async function cleanUrgent() {
  const blocks = await sql\`SELECT id, room_id, content FROM liturgical_blocks WHERE block_type = 'prayer'\`;
  console.log('Found prayer blocks:', blocks.length);

  for (const block of blocks) {
    if (!Array.isArray(block.content)) continue;
    let modified = false;
    const newContent = block.content.map(item => {
      if (item && item.urgent) {
        modified = true;
        const cleaned = { ...item };
        delete cleaned.urgent;
        return cleaned;
      }
      return item;
    });

    if (modified) {
      console.log('Cleaning urgent from block:', block.id, 'in room:', block.room_id);
      await sql\`
        UPDATE liturgical_blocks 
        SET content = \${JSON.stringify(newContent)}::jsonb, updated_at = NOW() 
        WHERE id = \${block.id}
      \`;
      await sql\`
        UPDATE rooms 
        SET version = version + 1, updated_at = NOW() 
        WHERE id = \${block.room_id}
      \`;
    }
  }
  console.log('Clean complete!');
}

cleanUrgent().catch(err => { console.error(err); process.exit(1); });
"

